use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant};

pub struct TimedCache<K, V> {
    inner: Arc<RwLock<HashMap<K, (V, Instant)>>>,
    ttl: Duration,
}

impl<K: Eq + std::hash::Hash, V: Clone> TimedCache<K, V> {
    pub fn new(ttl: Duration) -> Self {
        Self { inner: Arc::new(RwLock::new(HashMap::new())), ttl }
    }
    pub fn get(&self, key: &K) -> Option<V> {
        let map = self.inner.read().unwrap();
        map.get(key).and_then(|(v, t)| {
            if t.elapsed() < self.ttl { Some(v.clone()) } else { None }
        })
    }
    pub fn insert(&self, key: K, value: V) {
        let mut map = self.inner.write().unwrap();
        map.insert(key, (value, Instant::now()));
    }
}

